PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS professions(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, sha TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocks(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, locator TEXT NOT NULL, data TEXT NOT NULL, outcome TEXT NOT NULL, entity_id TEXT, reason TEXT);
CREATE TABLE IF NOT EXISTS materials(id TEXT PRIMARY KEY, source_id TEXT, code TEXT, profession TEXT, kind TEXT NOT NULL, status TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions(id INTEGER PRIMARY KEY, material_id TEXT NOT NULL, revision INTEGER NOT NULL, actor TEXT NOT NULL, created TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS relations(id TEXT PRIMARY KEY, origin TEXT NOT NULL, target TEXT, target_code TEXT, evidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, role TEXT NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS personal(user_id TEXT NOT NULL, kind TEXT NOT NULL, item TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(user_id,kind,item));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS taxonomy(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS imports(id INTEGER PRIMARY KEY, created TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS material_visibility ON materials(status,profession,kind);
